+}
+
+function renderValue(value: string): string {
+  if (PLAIN_VALUE_PATTERN.test(value)) return value;
+  const escaped = value.replace(/[\\"$\n\r]/g, (ch) => {
+    switch (ch) {
+      case "\n":
+        return "\\n";
+      case "\r":
+        return "\\r";
+      default:
+        return `\\${ch}`;
+    }
+  });
+  return `"${escaped}"`;
 }

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  const names = Object.keys(vars).sort();
+  for (const name of names) {
+    if (!NAME_PATTERN.test(name)) throw new RangeError(`invalid variable name: ${JSON.stringify(name)}`);
+  }
+  return names.map((name) => `${name}=${renderValue(vars[name])}\n`).join("");
 }

